pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Ensure lockInGuess does not revert: we need exactly 1 ether
        // Fund the contract with 1 ether from the test
        vm.deal(address(c), 2 ether);
        // Fund the caller with 1 ether
        vm.deal(address(this), 1 ether);
        // Call lockInGuess with hash and exactly 1 ether
        c.lockInGuess{value: 1 ether}(hash);
        // Now advance to a block where settle can be called (block number > guesses[msg.sender].block)
        // The locked block is block.number + 1, so we need to be at least block.number + 2
        // Use vm.roll to advance 2 blocks
        vm.roll(block.number + 2);
        // Record contract balance before settle
        uint balanceBefore = address(c).balance;
        // Call settle
        c.settle();
        uint balanceAfter = address(c).balance;
        // The rule: the contract should have transferred 2 ether if and only if the hash equals the answer
        // The answer is keccak256(blockhash(block.number - 1)) because guesses[msg.sender].block = block.number + 1 at lockInGuess time and we advanced by 2, so the locked block is block.number - 1
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        bool shouldTransfer = (hash == answer);
        if (shouldTransfer) {
            assertTrue(balanceAfter == balanceBefore - 2 ether);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

