    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash) public {
        // Ensure we have enough ether for the initial deposit and lockInGuess
        vm.deal(address(this), 3 ether);

        // First, we need to call lockInGuess which requires msg.value == 1 ether
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now we need to advance to the next block so that settle can work
        vm.roll(block.number + 2);

        // Record the contract's balance before settle
        uint256 balanceBefore = address(c).balance;

        // To make a correct guess, we need to know the blockhash of the block where lockInGuess was called.
        // The lockInGuess sets guesses[msg.sender].block = block.number + 1, so we need the blockhash of (original block + 1).
        // Since we rolled to block.number + 2, the answer is keccak256(blockhash(original block + 1)), which we know.
        // But we can't compute this here easily without knowing the exact block number. Instead, we'll try to win by brute force or assume we can guess correctly.
        // For a general rule, we can use vm.assume to only test when we can make a correct guess.
        // Actually, to keep the test general, we'll just call settle and check that the balance change is either 2 ether (correct guess) or 0 ether (wrong guess).
        // But the mutant changes the transfer to 1 ether, so we need a condition that distinguishes the two.
        // We can simulate a correct guess by computing the answer.
        // However, the blockhash is only available for recent blocks. We'll advance to the block where the guess was locked.
        // We'll do it differently: instead of trying to guess correctly, we'll use the fact that the contract's balance after settle is always either decreased by 2 ether (if correct) or unchanged (if incorrect) in the reference version.
        // In the buggy version, if correct, it decreases by 1 ether.
        // To force a correct guess, we can call lockInGuess with a hash that we know will match the answer.
        // We'll compute the answer by using vm.blockhash.
        uint256 lockBlock = block.number; // after lockInGuess, block.number is still the same, but guesses[msg.sender].block = block.number + 1
        // Actually lockInGuess sets block = block.number + 1, so answer block is block.number + 1
        uint256 answerBlock = block.number + 1;
        // We cannot predict the future blockhash, but we can set it with vm.roll and then compute.
        // Let's use vm.warp and vm.roll to set a known block number.
        vm.roll(100);
        // Now call lockInGuess at block 100, which will set answer block to 101.
        c.lockInGuess{value: 1 ether}(guessHash);
        // Now roll to block 102 to satisfy block.number > answerBlock
        vm.roll(102);
        // Compute the answer using blockhash of 101 (which is available because we are at block 102 and it's within 256 blocks)
        bytes32 answer = keccak256(abi.encodePacked(blockhash(101)));
        // But we passed guessHash, not necessarily answer. So to make a correct guess, we need to pass guessHash = answer.
        // Better: we'll call lockInGuess with the answer as hash, but we need to know answer first.
        // So we can do: first compute answer, then set up a new user and call lockInGuess with that answer.
        // To keep it simple, we'll just pick a guessHash that we know will be wrong, and then assert about balance after settle.
        // For a general property, we can assert that the balance change is either 0 or 2 ether (reference) vs 0 or 1 ether (buggy).
        // Since we cannot guarantee a correct guess, we can use a property that holds for both correct and incorrect guesses but distinguishes the amounts.
        // We'll just rely on the fact that the contract's balance after settle is always >= initial balance - 2 ether (reference) vs >= initial balance - 1 ether (buggy). That's not a strict difference.
        // Better: we enforce a correct guess by computing the answer and using it.
        // Let's use a fresh address and vm.prank.
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        // We'll record the block number before calling
        uint256 startBlock = 200;
        vm.roll(startBlock);
        c.lockInGuess{value: 1 ether}(guessHash);
        uint256 answerBlock2 = startBlock + 1;
        vm.roll(answerBlock2 + 1);
        bytes32 answer2 = keccak256(abi.encodePacked(blockhash(answerBlock2)));
        // To make a correct guess, we need guessHash == answer2. But guessHash is a fuzz parameter, so we can vm.assume that.
        vm.assume(guessHash == answer2);
        // Now the guess is correct. Settle as user
        vm.prank(user);
        uint256 balBeforeSettle = address(c).balance;
        c.settle();
        uint256 balAfterSettle = address(c).balance;
        // In reference, balAfterSettle == balBeforeSettle - 2 ether (since transfer sends 2 ether to user)
        // In buggy, it's balBeforeSettle - 1 ether.
        assertTrue(balAfterSettle == balBeforeSettle - 2 ether, "Balance should decrease by exactly 2 ether on correct guess");
    }
