pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 guessHash, uint256 blockNumber) public {
        // Ensure we can mine blocks to reach a future block
        vm.assume(blockNumber > block.number + 1);
        vm.assume(blockNumber < block.number + 256);

        // Pre-fund the user
        address user = address(this);
        vm.deal(user, 2 ether);

        // Lock in a guess
        c.lockInGuess{value: 1 ether}(guessHash);

        // Fast forward to the target block
        vm.roll(blockNumber);

        // Record balance before settle
        uint256 balanceBefore = user.balance;

        // Attempt settle
        (bool success,) = address(c).call(abi.encodeWithSignature("settle()"));

        // If the guess was correct (i.e., hash matches blockhash), then exactly 2 ether should be transferred
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(blockNumber - 1)));
        bool guessCorrect = (guessHash == expectedAnswer);

        if (guessCorrect) {
            // settle must succeed and transfer exactly 2 ether
            assertTrue(success, "settle should succeed for correct guess");
            assertTrue(user.balance == balanceBefore + 2 ether, "Settling correct guess should transfer exactly 2 ether");
        } else {
            // For incorrect guess, no transfer should happen after the lock expires (but may revert or succeed)
            // General rule: if settle succeeds, balance unchanged except for gas costs
            // We just check the main property: when guess is correct, transfer amount is exactly 2 ether
            if (success) {
                assertTrue(user.balance <= balanceBefore, "Settling incorrect guess should not increase balance");
            }
        }
    }
}

