        vm.roll(block.number + 2);

        // We need to know the correct answer: keccak256(abi.encodePacked(blockhash(block.number - 1)))
        // Forge cheatcodes don't give us blockhash for future blocks, so we use vm.store to manipulate the guess.
        // Instead, we make the guess always equal to the answer by using vm.assume to ensure the blockhash isn't zero
        vm.assume(blockhash(block.number - 1) != bytes32(0));

        // We cannot directly set the guess, but we can call settle and check balance change
        // Since we don't know the answer, we treat any outcome: either correct (transfer 2 ether) or incorrect (no transfer)
        // The invariant: if correct guess, balance decreases by exactly 2 ether; if incorrect, balance unchanged
        // To force correctness, we set the guess via storage to match the answer
        // Use vm.store to set the guess mapping value for this address
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        // The guess is stored in slot of mapping(address => Guess) where slot for key address(this) is: keccak256(abi.encode(address(this), 0))
        bytes32 slot = keccak256(abi.encode(address(this), uint256(0)));
        vm.store(address(c), slot + bytes32(uint256(0)), bytes32(uint256(block.number - 1))); // block field
        vm.store(address(c), slot + bytes32(uint256(1)), answer); // guess field

        // Now call settle
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // The balance must have decreased by exactly 2 ether because our guess is correct
        assertTrue(balanceBefore - balanceAfter == 2 ether, "Balance should decrease by 2 ether on correct guess");
    }
}

